sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.filter = 'all';
  c.q = '';
  c.setFilter = function(f) { c.filter = f; };
  c.match = function(r) {
    if (c.filter !== 'all' && r.level !== c.filter) return false;
    return !c.q || r.service.toLowerCase().indexOf(c.q.toLowerCase()) > -1;
  };
  c.count = function(f) {
    return c.data.rows.filter(function(r) { return f === 'all' || r.level === f; }).length;
  };
};

sp_widget.css:
.cpm { color: #1f2937; }
.cpm * { box-sizing: border-box; }

.cpm-hero { display: flex; justify-content: space-between; align-items: center;
  padding: 24px 28px; border-radius: 16px; color: #fff; margin-bottom: 18px;
  background: linear-gradient(135deg, #0f172a 0%, #1e3a8a 60%, #0e7490 100%); }
.cpm-hero h2 { margin: 4px 0; font-size: 26px; color: #fff; }
.cpm-hero p { margin: 0; opacity: .8; }
.cpm-eyebrow { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; opacity: .7; }
.cpm-hero-ring { position: relative; width: 92px; height: 92px; flex: none; }
.cpm-hero-ring svg { width: 100%; height: 100%; }
.cpm-hero-ring-label { position: absolute; top: 0; left: 0; right: 0; bottom: 0; display: flex;
  flex-direction: column; align-items: center; justify-content: center; }
.cpm-hero-ring-label b { font-size: 21px; line-height: 1; }
.cpm-hero-ring-label span { font-size: 10px; opacity: .7; }
.cpm-hero .track { fill: none; stroke: rgba(255,255,255,.2); stroke-width: 7; }
.cpm-hero .bar { fill: none; stroke: #5eead4; stroke-width: 7; stroke-linecap: round; }

.cpm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; margin-bottom: 20px; }
.cpm-kpi { background: #fff; border-radius: 12px; padding: 14px 16px; border: 1px solid #e5e7eb; border-left: 4px solid #3b82f6; }
.cpm-kpi b { display: block; font-size: 26px; line-height: 1.1; }
.cpm-kpi span { font-size: 12px; color: #6b7280; }
.cpm-kpi.warn { border-left-color: #f59e0b; }
.cpm-kpi.danger { border-left-color: #ef4444; }

.cpm-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 14px; }
.cpm-chips button { border: 1px solid #d1d5db; background: #fff; border-radius: 999px;
  padding: 6px 14px; margin-right: 6px; font-size: 13px; cursor: pointer; }
.cpm-chips button.active { background: #1e3a8a; color: #fff; border-color: #1e3a8a; }
.cpm-search { border: 1px solid #d1d5db; border-radius: 10px; padding: 8px 12px; min-width: 220px; }

.cpm-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(270px, 1fr)); gap: 16px; margin-bottom: 22px; }
.cpm-card { display: block; background: #fff; border-radius: 16px; padding: 18px; color: inherit;
  border: 1px solid #e5e7eb; transition: transform .15s, box-shadow .15s; }
.cpm-card:hover { transform: translateY(-3px); box-shadow: 0 10px 24px rgba(15,23,42,.12); text-decoration: none; color: inherit; }
.cpm-card-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.cpm-card-title { font-weight: 600; font-size: 16px; margin-bottom: 4px; }
.cpm-ring { width: 64px; height: 64px; flex: none; }
.cpm-ring .track { fill: none; stroke: #e5e7eb; stroke-width: 7; }
.cpm-ring .bar { fill: none; stroke-width: 7; stroke-linecap: round; }
.cpm-ring text { font-size: 15px; font-weight: 700; fill: #111827; }
.level-ok .bar { stroke: #16a34a; }    .level-ok .cpm-badge { background: #dcfce7; color: #166534; }
.level-warn .bar { stroke: #f59e0b; }  .level-warn .cpm-badge { background: #fef3c7; color: #92400e; }
.level-danger .bar { stroke: #ef4444; } .level-danger .cpm-badge { background: #fee2e2; color: #991b1b; }
.cpm-badge { font-size: 11px; padding: 2px 10px; border-radius: 999px; font-weight: 600; }
.cpm-card-stats { display: grid; grid-template-columns: repeat(4, 1fr); text-align: center; border-top: 1px solid #f3f4f6; padding-top: 12px; }
.cpm-card-stats b { display: block; font-size: 18px; }
.cpm-card-stats span { font-size: 11px; color: #6b7280; }
.cpm-empty { grid-column: 1 / -1; text-align: center; color: #6b7280; padding: 30px; }

.cpm-panels { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 16px; }
.cpm-panel { background: #fff; border-radius: 16px; padding: 16px 20px; border: 1px solid #e5e7eb; }
.cpm-panel h4 { margin: 0 0 10px; font-size: 15px; }
.cpm-row { display: flex; justify-content: space-between; gap: 10px; padding: 9px 0; border-top: 1px solid #f3f4f6; font-size: 14px; }
.cpm-row small { display: block; color: #6b7280; }
.cpm-row em { font-style: normal; font-size: 12px; color: #b45309; background: #fef3c7; padding: 2px 8px; border-radius: 8px; align-self: center; white-space: nowrap; }
.cpm-ok { color: #166534; font-size: 14px; padding: 6px 0; }

sp_widget.script:
(function() {
  data.rows = [];
  data.expiring = [];
  data.unmapped = [];
  data.kpi = { coverage: 0, services: 0, controls: 0, expiring: 0, expired: 0, unmapped: 0 };

  var mappedIds = [], sumEvidenced = 0, sumTotal = 0;

  var gr = new GlideRecordSecure('x_1929776_compli_0_service_posture');
  gr.orderBy('coverage_pct');
  gr.query();
  while (gr.next()) {
    var total = parseInt(gr.getValue('total_controls'), 10) || 0;
    if (total === 0) continue;
    var pct = parseInt(gr.getValue('coverage_pct'), 10) || 0;
    var evidenced = parseInt(gr.getValue('with_valid_evidence'), 10) || 0;
    mappedIds.push(gr.getValue('business_service'));
    sumEvidenced += evidenced;
    sumTotal += total;
    data.rows.push({
      sys_id: gr.getValue('business_service'),
      service: gr.getDisplayValue('business_service'),
      pct: pct,
      total: total,
      implemented: parseInt(gr.getValue('implemented'), 10) || 0,
      evidenced: evidenced,
      gap: total - evidenced,
      level: pct < 50 ? 'danger' : (pct < 80 ? 'warn' : 'ok')
    });
  }
  data.kpi.services = data.rows.length;
  data.kpi.controls = sumTotal;
  data.kpi.coverage = sumTotal ? Math.round(sumEvidenced / sumTotal * 100) : 0;

  var ag = new GlideAggregate('x_1929776_compli_0_evidence');
  ag.addAggregate('COUNT');
  ag.groupBy('state');
  ag.query();
  while (ag.next()) {
    var n = parseInt(ag.getAggregate('COUNT'), 10);
    if (ag.getValue('state') == 'expiring') data.kpi.expiring = n;
    if (ag.getValue('state') == 'expired') data.kpi.expired = n;
  }

  var svc = new GlideRecordSecure('cmdb_ci_service');
  if (mappedIds.length) svc.addQuery('sys_id', 'NOT IN', mappedIds.join(','));
  svc.addQuery('name', 'IN', 'Prepaid Billing,Customer CRM,Payment Gateway,Mobile Data Service');
  svc.orderBy('name');
  svc.query();
  while (svc.next()) {
    data.kpi.unmapped++;
    if (data.unmapped.length < 8) data.unmapped.push({ name: svc.getValue('name') });
  }

  var ev = new GlideRecordSecure('x_1929776_compli_0_evidence');
  ev.addQuery('state', 'expiring');
  ev.orderBy('valid_until');
  ev.setLimit(5);
  ev.query();
  while (ev.next()) {
    data.expiring.push({
      title: ev.getValue('title'),
      control: ev.mapping.control.name + '',
      service: ev.mapping.business_service.getDisplayValue(),
      until: ev.getValue('valid_until')
    });
  }
})();
